    explanation: '御成敗式目（貞永式目）は鎌倉幕府3代執権・北条泰時が1232年に制定した武家法。守護・地頭の職務・権限、武士の所領相続、訴訟手続きなど51か条を明文化した。従来の慣習法を成文法にまとめ、公家法（律令）とは別に武士社会独自の法規範を確立した意義がある。その後の室町幕府の追加法令・分国法の模範となり、武家法の出発点として重要。',
