    explanation: '英国では1642年清教徒革命でチャールズ1世が処刑され共和制が成立、1688年名誉革命で「権利章典」が制定され議会主権が確立された（最も穏健）。米国独立革命（1776年）はロックの思想を基に「人間の平等と生命・自由・幸福追求の権利」を天賦人権として宣言し民主的共和国を建設した。フランス革命（1789年）はアンシャン・レジーム（旧体制）を暴力的に打倒し人権宣言・共和制・ナポレオンによる革命の輸出と歴史の激動をもたらした。三革命の共通点は絶対君主制に対して人民の権利を要求した点。',
